using System.Security.Cryptography;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using PhoneStore.Api.Data;
using PhoneStore.Api.DTOs.Common;
using PhoneStore.Api.DTOs.Surveys;
using PhoneStore.Api.Entities;
using PhoneStore.Api.Services.Auth;
using PhoneStore.Api.Services.Checkout;
using PhoneStore.Api.Services.Membership;
namespace PhoneStore.Api.Services.Surveys;
public sealed class SurveyService(AppDbContext db,TimeProvider clock,AuthBootstrap users){
 private DateTime Now=>new(clock.GetUtcNow().UtcTicks/10000*10000,DateTimeKind.Utc);
 private static CheckoutException Error(int status,string code)=>new(status,code,"Khảo sát hoặc câu trả lời không hợp lệ. Hãy tải lại và kiểm tra thông tin.");
 private static string Text(string? value,int max,bool required=true){var text=value?.Trim().Normalize()??"";if((required&&text.Length==0)||text.Length>max)throw Error(400,"VALIDATION_ERROR");return text;}
 private static long Id(string? value)=>ApiContract.TryParseId(value,out var id)?id:throw Error(400,"VALIDATION_ERROR");
 private static void Page(PageQuery page){if(page.Offset>int.MaxValue)throw Error(400,"INVALID_FILTER");}
 private async Task Actor(Guid actor,CancellationToken ct){await MembershipService.LockAsync(db,false,ct);await users.LockUserAsync(actor,ct);if(!await db.Users.AnyAsync(u=>u.Id==actor&&u.IsActive&&u.EmailConfirmed,ct))throw Error(401,"UNAUTHENTICATED");}
 private IQueryable<Survey> Query()=>db.Surveys.Include(s=>s.Questions).ThenInclude(q=>q.Options).AsSplitQuery();
 private static SurveyDto Dto(Survey s)=>new(s.Id.ToString(),s.Title,s.Description,s.Status.ToString(),s.StartsAt,s.EndsAt,Convert.ToBase64String(s.Version),s.Questions.OrderBy(q=>q.SortOrder).Select(q=>new SurveyQuestionDto(q.Id.ToString(),q.Text,q.Type.ToString(),q.IsRequired,q.Options.OrderBy(o=>o.SortOrder).Select(o=>new SurveyOptionDto(o.Id.ToString(),o.Text)).ToArray())).ToArray());
 private bool Active(Survey s)=>s.Status==SurveyStatus.Published&&s.StartsAt<=Now&&Now<s.EndsAt;
 private static byte[] Version(string? header){if(header is null)throw Error(428,"PRECONDITION_REQUIRED");if(!ApiContract.TryParseETag(header,out var version))throw Error(400,"INVALID_ETAG");return version;}
 private void Audit(long id,Guid actor,string action,string hash)=>db.AuditLogs.Add(new(){ActorUserId=actor,Action="Survey."+action,EntityType="Survey",EntityId=id.ToString(),Summary="sha256:"+hash,CorrelationId=Guid.NewGuid().ToString(),CreatedAt=Now});
 public async Task<PagedResponse<SurveySummary>> List(Guid actor,bool admin,PageQuery page,CancellationToken ct){Page(page);await using var tx=await db.Database.BeginTransactionAsync(ct);await Actor(actor,ct);var now=Now;var q=db.Surveys.AsNoTracking();if(!admin)q=q.Where(s=>s.Status==SurveyStatus.Published&&s.StartsAt<=now&&s.EndsAt>now);var total=await q.LongCountAsync(ct);var items=await q.OrderByDescending(s=>s.CreatedAt).ThenByDescending(s=>s.Id).Skip((int)page.Offset).Take(page.PageSize).Select(s=>new SurveySummary(s.Id.ToString(),s.Title,s.Description,s.Status.ToString(),s.StartsAt,s.EndsAt,s.Responses.Any(r=>r.UserId==actor))).ToListAsync(ct);await tx.CommitAsync(ct);return new(items,page.Page,page.PageSize,total);}
 public async Task<SurveyDto> Read(long id,Guid actor,bool admin,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);await Actor(actor,ct);var s=await Query().AsNoTracking().SingleOrDefaultAsync(s=>s.Id==id,ct)??throw Error(404,"NOT_FOUND");if(!admin&&!Active(s))throw Error(404,"NOT_FOUND");var result=Dto(s);await tx.CommitAsync(ct);return result;}
 private static void Validate(SurveyInput input){Text(input.Title,200);Text(input.Description,2000,false);if(input.StartsAt.Kind!=DateTimeKind.Utc||input.EndsAt.Kind!=DateTimeKind.Utc||input.StartsAt.Ticks/10000>=input.EndsAt.Ticks/10000||input.Questions is not{Count:>0 and <=50})throw Error(400,"VALIDATION_ERROR");foreach(var q in input.Questions){if(q is null||!Enum.TryParse<SurveyQuestionType>(q.Type,out var type)||type.ToString()!=q.Type||q.Options is null||type==SurveyQuestionType.Text&&q.Options.Count!=0||type!=SurveyQuestionType.Text&&(q.Options.Count<2||q.Options.Count>20))throw Error(400,"VALIDATION_ERROR");Text(q.Text,1000);var options=q.Options.Select(o=>Text(o,500)).ToArray();if(options.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=options.Length)throw Error(400,"VALIDATION_ERROR");}}
 public async Task<SurveyReceipt> Write(long? id,Guid actor,string? match,SurveyInput? input,string action,Guid operation,CancellationToken ct){
  if(operation==Guid.Empty)throw Error(400,"VALIDATION_ERROR");var version=id is null?[]:Version(match);if(input is not null)Validate(input);var key="Survey.Operation:"+operation.ToString("D");var hash=Convert.ToHexStringLower(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(new{id,actor,match,input,action})));
  await using var tx=await db.Database.BeginTransactionAsync(ct);await Actor(actor,ct);await db.Database.ExecuteSqlInterpolatedAsync($"DECLARE @r int; EXEC @r=sys.sp_getapplock @Resource={key},@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=10000; IF @r<0 THROW 51004,'Survey operation busy.',1;",ct);
  var prior=await db.OutboxMessages.AsNoTracking().SingleOrDefaultAsync(m=>m.EventKey==key,ct);if(prior is not null){using var json=JsonDocument.Parse(prior.PayloadJson);if(json.RootElement.GetProperty("hash").GetString()!=hash)throw Error(409,"OPERATION_KEY_MISMATCH");var receipt=json.RootElement.GetProperty("receipt").Deserialize<SurveyReceipt>()!;await tx.CommitAsync(ct);return receipt;}
  Survey s;if(id is null){s=new(){CreatedAt=Now,CreatedByUserId=actor};db.Surveys.Add(s);}else{ s=await db.Surveys.FromSqlInterpolated($"SELECT * FROM [Surveys] WITH (XLOCK,HOLDLOCK) WHERE [Id]={id}").SingleOrDefaultAsync(ct)??throw Error(404,"NOT_FOUND");if(!CryptographicOperations.FixedTimeEquals(version,s.Version))throw Error(412,"VERSION_CONFLICT");await db.Entry(s).Collection(x=>x.Questions).LoadAsync(ct);foreach(var q in s.Questions)await db.Entry(q).Collection(x=>x.Options).LoadAsync(ct);}
  if(input is not null){if(s.Status!=SurveyStatus.Draft)throw Error(409,"SURVEY_FROZEN");if(id is not null){if(await db.SurveyResponses.AnyAsync(r=>r.SurveyId==s.Id,ct))throw Error(409,"SURVEY_FROZEN");db.SurveyOptions.RemoveRange(s.Questions.SelectMany(q=>q.Options));db.SurveyQuestions.RemoveRange(s.Questions);s.Questions.Clear();await db.SaveChangesAsync(ct);}
   s.Title=Text(input.Title,200);s.Description=string.IsNullOrWhiteSpace(input.Description)?null:Text(input.Description,2000);s.StartsAt=new DateTime(input.StartsAt.Ticks/10000*10000,DateTimeKind.Utc);s.EndsAt=new DateTime(input.EndsAt.Ticks/10000*10000,DateTimeKind.Utc);
   for(var n=0;n<input.Questions.Count;n++){var q=input.Questions[n];var entity=new SurveyQuestion{Text=Text(q.Text,1000),Type=Enum.Parse<SurveyQuestionType>(q.Type),IsRequired=q.IsRequired,SortOrder=n};for(var j=0;j<q.Options.Count;j++)entity.Options.Add(new(){Text=Text(q.Options[j],500),SortOrder=j});s.Questions.Add(entity);}if(id is not null)db.Entry(s).Property(x=>x.Title).IsModified=true;
  }else if(action=="Publish"){if(s.Status!=SurveyStatus.Draft||s.EndsAt<=Now||s.Questions.Count==0)throw Error(409,"SURVEY_UNAVAILABLE");s.Status=SurveyStatus.Published;}else if(action=="Close"){if(s.Status!=SurveyStatus.Published)throw Error(409,"SURVEY_UNAVAILABLE");s.Status=SurveyStatus.Closed;}else throw Error(400,"VALIDATION_ERROR");
  await db.SaveChangesAsync(ct);var result=new SurveyReceipt(s.Id.ToString(),s.Status.ToString(),Convert.ToBase64String(s.Version));Audit(s.Id,actor,action,hash);db.OutboxMessages.Add(new(){Type="SurveyOperation",EventKey=key,PayloadJson=JsonSerializer.Serialize(new{hash,receipt=result}),CreatedAt=Now,NextAttemptAt=Now,ProcessedAt=Now});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return result;
 }
 public async Task<SurveySubmission> Status(long id,Guid user,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);await Actor(user,ct);var s=await db.Surveys.AsNoTracking().SingleOrDefaultAsync(s=>s.Id==id,ct)??throw Error(404,"NOT_FOUND");var r=await db.SurveyResponses.AsNoTracking().SingleOrDefaultAsync(r=>r.SurveyId==id&&r.UserId==user,ct);if(r is null&&!Active(s))throw Error(404,"NOT_FOUND");await tx.CommitAsync(ct);return new(id.ToString(),r is not null,r?.SubmittedAt);}
 public async Task<SurveySubmission> Submit(long id,Guid user,SurveySubmit input,CancellationToken ct){
  if(input.Answers is null||input.Answers.Count>50||input.Answers.Any(a=>a is null))throw Error(400,"VALIDATION_ERROR");await using var tx=await db.Database.BeginTransactionAsync(ct);await Actor(user,ct);var s=await db.Surveys.FromSqlInterpolated($"SELECT * FROM [Surveys] WITH (XLOCK,HOLDLOCK) WHERE [Id]={id}").SingleOrDefaultAsync(ct)??throw Error(404,"NOT_FOUND");if(await db.SurveyResponses.AnyAsync(r=>r.SurveyId==id&&r.UserId==user,ct))throw Error(409,"ALREADY_RESPONDED");if(!Active(s))throw Error(409,"SURVEY_UNAVAILABLE");await db.Entry(s).Collection(x=>x.Questions).LoadAsync(ct);foreach(var q in s.Questions)await db.Entry(q).Collection(x=>x.Options).LoadAsync(ct);
  var questionIds=input.Answers.Select(a=>Id(a.QuestionId)).ToArray();if(questionIds.Distinct().Count()!=questionIds.Length)throw Error(400,"SURVEY_INVALID_ANSWER");var supplied=input.Answers.ToDictionary(a=>Id(a.QuestionId),a=>a); // Duplicate keys are rejected before persistence.
  if(supplied.Count!=input.Answers.Count||supplied.Keys.Any(key=>s.Questions.All(q=>q.Id!=key)))throw Error(400,"SURVEY_INVALID_ANSWER");
  var response=new SurveyResponse{SurveyId=id,UserId=user,SubmittedAt=Now};foreach(var q in s.Questions){supplied.TryGetValue(q.Id,out var a);var choices=(a?.OptionIds??[]).Select(x=>Id(x)).ToArray();if(choices.Length>20||choices.Distinct().Count()!=choices.Length||choices.Any(choice=>q.Options.All(o=>o.Id!=choice)))throw Error(400,"SURVEY_INVALID_ANSWER");var text=a?.TextValue is null?null:Text(a.TextValue,4000,false);
   if(q.Type==SurveyQuestionType.Text){if(choices.Length>0)throw Error(400,"SURVEY_INVALID_ANSWER");if(string.IsNullOrEmpty(text)){if(q.IsRequired)throw Error(400,"SURVEY_REQUIRED_ANSWERS");continue;}response.Answers.Add(new(){SurveyId=id,QuestionId=q.Id,TextValue=text});}
   else{if(a?.TextValue is not null||q.Type==SurveyQuestionType.SingleChoice&&choices.Length>1)throw Error(400,"SURVEY_INVALID_ANSWER");if(choices.Length==0){if(q.IsRequired)throw Error(400,"SURVEY_REQUIRED_ANSWERS");continue;}var answer=new SurveyAnswer{SurveyId=id,QuestionId=q.Id};foreach(var choice in choices)answer.SelectedOptions.Add(new(){QuestionId=q.Id,OptionId=choice});response.Answers.Add(answer);}
  }
  db.SurveyResponses.Add(response);await db.SaveChangesAsync(ct);Audit(id,user,"Submit",Convert.ToHexStringLower(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(input))));await db.SaveChangesAsync(ct);if(!Active(s))throw Error(409,"SURVEY_UNAVAILABLE");await tx.CommitAsync(ct);return new(id.ToString(),true,response.SubmittedAt);
 }
 public async Task<SurveyResults> Results(long id,Guid actor,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);await Actor(actor,ct);var s=await Query().AsNoTracking().SingleOrDefaultAsync(s=>s.Id==id,ct)??throw Error(404,"NOT_FOUND");var count=await db.SurveyResponses.LongCountAsync(r=>r.SurveyId==id,ct);var answerCounts=await db.SurveyAnswers.Where(a=>a.SurveyId==id).GroupBy(a=>a.QuestionId).Select(g=>new{Id=g.Key,Count=g.LongCount()}).ToListAsync(ct);var optionCounts=await db.SurveyAnswerOptions.Where(o=>o.Answer.SurveyId==id).GroupBy(o=>o.OptionId).Select(g=>new{Id=g.Key,Count=g.LongCount()}).ToListAsync(ct);var questions=s.Questions.OrderBy(q=>q.SortOrder).Select(q=>new SurveyQuestionResult(q.Id.ToString(),q.Text,q.Type.ToString(),q.IsRequired,answerCounts.SingleOrDefault(x=>x.Id==q.Id)?.Count??0,q.Options.Sum(o=>optionCounts.SingleOrDefault(x=>x.Id==o.Id)?.Count??0),q.Options.OrderBy(o=>o.SortOrder).Select(o=>new SurveyOptionResult(o.Id.ToString(),o.Text,optionCounts.SingleOrDefault(x=>x.Id==o.Id)?.Count??0)).ToArray())).ToArray();await tx.CommitAsync(ct);return new(id.ToString(),s.Title,count,questions);}
 public async Task<PagedResponse<SurveyTextResult>> TextResults(long id,long question,Guid actor,PageQuery page,CancellationToken ct){Page(page);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);await Actor(actor,ct);if(!await db.SurveyQuestions.AnyAsync(q=>q.Id==question&&q.SurveyId==id&&q.Type==SurveyQuestionType.Text,ct))throw Error(404,"NOT_FOUND");var q=db.SurveyAnswers.AsNoTracking().Where(a=>a.SurveyId==id&&a.QuestionId==question&&a.TextValue!=null);var count=await q.LongCountAsync(ct);var rows=await q.OrderByDescending(a=>a.Response.SubmittedAt).ThenByDescending(a=>a.Id).Skip((int)page.Offset).Take(page.PageSize).Select(a=>new SurveyTextResult(a.Id.ToString(),a.TextValue!,a.Response.SubmittedAt)).ToListAsync(ct);await tx.CommitAsync(ct);return new(rows,page.Page,page.PageSize,count);}
}
